import React, { useState } from 'react';
import axios from 'axios';
import { Container, Typography } from '@mui/material';
import Switch from '@mui/material/Switch';
import FormGroup from '@mui/material/FormGroup';
import FormControlLabel from '@mui/material/FormControlLabel';
import BlastLogo from '../assets/images/blast_logo.png';
import { useTheme } from '@mui/material/styles';
import InfoIcon from '@mui/icons-material/Info';
import
IconButton from '@mui/material/IconButton';
import Tooltip from '@mui/material/Tooltip';
import '../App.css';
const BlastSearch = ( ) => {
  const theme = useTheme();
  const [sequence, setSequence] = useState('');
  const [results, setResults] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);


  const [isExpanded, setIsExpanded] = useState(false);

  const toggleExpand = () => {
    setIsExpanded(!isExpanded);
  };

  const displayResults = isExpanded ? results : results.slice(0, 400);

 

  const handleChange = (e) => {
    setSequence(e.target.value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setResults("");

    try {
      const response = await axios.post('http://localhost:5000/api/blastn', { sequence });
      setResults(response.data.results);
    } catch (err) {
      setError(err.response ? err.response.data.error : err.message);
    } finally {
      setLoading(false);
    }
  };

  const label = { inputProps: { 'aria-label': 'Switch demo' } };

  return (
    <Container
    id="dashboard"
    sx={{
      pt: { xs: 4, sm: 12 },
      pb: { xs: 8, sm: 16 },
      position: "relative",
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      gap: { xs: 3, sm: 6 },
    }}
  >
    <div>
      <img src={BlastLogo} alt="BLAST Logo" style={{ width: '100%' }} />
      <p>
        Enter a 16S rRNA sequence in FASTA format to search for similar sequences
        <Tooltip title=" BASIC LOCAL ALIGNMENT SEARCH TOOL Current Sp: Mesorhizobium sp.  | Uncultured bacterium clone  | Paenibacillus sabinae strain T27  | Bradyrhizobium sp. ">
  <IconButton>
    <InfoIcon />
  </IconButton>
</Tooltip>

    
      </p>
      <form onSubmit={handleSubmit}>
      <textarea
  
  value={sequence}
  onChange={handleChange}
  rows="10"
  cols="50"
  placeholder="Enter 16S rRNA sequence in FASTA format"
  style={{
    color: theme.palette.mode === 'dark' ? 'white' : theme.palette.text.primary,
      width: '100%',
    borderRadius: '10px',
    backgroundColor: 'transparent',
    border: '1px solid #ccc',
    padding: '10px'
  }}
/>
        <br />
        <button 
  variant="contained" 
  type="submit" 
  disabled={loading} 
  style={{ 
    backgroundColor: '#66bb6a', 
    color: 'white', 
    border: 'none', 
    padding: '10px 20px', 
    borderRadius: '10px', 
    cursor: 'pointer' ,
    fontWeight: 'bold' // Make the text bold
  }}
>
  {loading ? 'Searching...' : 'Search'}
</button>
      </form>
      {error && <p>{error}</p>}
<br/>
{results.length > 400 && <Typography component="h2" variant="h4" color="text.primary">RESULTS</Typography>
}
      {results.length > 500 && (
           <FormGroup>
          <FormControlLabel control={ <Switch  {...label} checked={isExpanded} onChange={toggleExpand}/>} label="See Expanded Results" />
          
          </FormGroup>
          )}
      <div>
      {results && (
        <pre>
          {displayResults}
          
        </pre>
      )}
    </div>
    </div>
    </Container>
  );
};

export default BlastSearch;
